import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`customer-journey-map`,heroTitle:`Map your customer journey in minutes`,heroSubtitle:`Perplexity Computer analyzes your funnel and your competitor's, identifies drop-off points, and delivers a journey map with fix recommendations - automatically.`,inputUrlCta:`Map my journey`,inputUrlPlaceholder:`www.yoursite.com`,inputUrlPrefill:`Go to {url} and perform a full customer journey audit across this brand and its top competitor. 1) Analyze the site to identify every touchpoint in the funnel - ads, landing pages, email capture forms, nurture sequences, retargeting pixels, review site presence, social proof elements, and post-purchase flows. 2) Identify the brand's top competitor and map the same touchpoints across their funnel. 3) Compare both journeys side by side - flag where prospects drop off, where competitors intercept with better messaging or retargeting, and where gaps exist in channel coverage. 4) Score each stage of the funnel (awareness, consideration, decision, retention) for both brands. 5) Deliver a visual customer journey map with specific recommendations for each gap - including suggested copy, channel, timing, and priority level. 6) Produce an action plan spreadsheet with columns: funnel stage, touchpoint, current status, competitor status, gap description, recommended fix, suggested copy, channel, timing, and priority score.`,heroOverlaySteps:[`Analyzing your site to map every funnel touchpoint and conversion flow`,`Analyzing your top competitor's journey - ads, emails, retargeting, social proof`,`Identifying drop-off points and competitor interception opportunities`,`Journey map, gap analysis, and channel recommendations - ready to execute`],generatingSteps:[`Visiting {url} to extract your funnel touchpoints, messaging, and conversion flows`,`Designing an agent to map your competitor's journey and compare every stage side by side`,`Configuring drop-off detection, competitor interception analysis, and funnel scoring`,`Setting up your journey map deliverable with copy, channel, and timing recommendations`],featureSectionTitle:`From URLs to customer journey map`,featureCardTitles:[`Connects to your marketing stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Analytics, Google Sheets, Notion, Slack, Airtable - Computer plugs into your tools so journey insights flow straight into your campaigns and planning docs.`,`Visual customer journey maps. Stage-by-stage funnel scores. Competitor interception analysis. Gap-specific copy and channel recommendations. Prioritized action plan spreadsheet.`],capabilitySectionTitle:`Your journey strategist, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to a complete customer journey strategy.`,capabilityCards:[{title:`Funnel Mapping`,description:`Computer can analyze your site and map every touchpoint - ads, landing pages, email sequences, retargeting, review sites, and social proof - into a structured journey view.`},{title:`Competitor Comparison`,description:`Computer can map your top competitor's funnel side by side with yours - and pinpoint exactly where they intercept your prospects with better messaging or coverage.`},{title:`Drop-Off Detection`,description:`Computer can identify where prospects abandon your funnel - and recommend specific copy, channel, and timing fixes to close each gap.`},{title:`Connect Your Tools`,description:`Computer can pull data from Google Analytics, Google Search Console, Notion, Slack, and more - build workflows across your entire marketing stack.`},{title:`Remember & Learn`,description:`Computer can remember your funnel structure, competitors, and past journey audits - so every analysis tracks improvements and surfaces new gaps.`},{title:`Monitor & Alert`,description:`Computer can re-audit your journey monthly and flag when competitors launch new touchpoints or your drop-off rates shift.`}]});export{t as default};
